import{c as t,J as o,h as r,k as a}from"./chunks/framework.NhpCCunm.js";const u=JSON.parse('{"title":"Web Store & Showcase","description":"Built-in Static Site Generator (Jamstack SSG), Order Inbox, and publishing transport in OmniCraft ERP.","frontmatter":{"title":"Web Store & Showcase","description":"Built-in Static Site Generator (Jamstack SSG), Order Inbox, and publishing transport in OmniCraft ERP.","order":9},"headers":[],"relativePath":"docs/spaces/production/web-store.md","filePath":"docs/spaces/production/web-store.md"}'),i={name:"docs/spaces/production/web-store.md"};function s(n,e,l,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="craft-web-store-showcase" tabindex="-1">Craft Web Store &amp; Showcase <a class="header-anchor" href="#craft-web-store-showcase" aria-label="Permalink to &quot;Craft Web Store &amp; Showcase&quot;">​</a></h1><p>The built-in <strong>Web Store &amp; Showcase</strong> module enables craftsmen to transform their product recipes and catalog into an autonomous, lightning-fast static website catalog in a single click without recurring monthly fees for proprietary site builders.</p><p>The showcase is compiled using <strong>Jamstack (Static Site Generation)</strong>: the output consists of pure HTML, CSS, and lightweight JavaScript with zero server-side vulnerabilities. The generated site loads instantly on mobile and desktop devices and can be hosted for free on GitHub Pages, S3 cloud storages (Yandex Cloud, Selectel, AWS, MinIO), or via FTP.</p><hr><h2 id="architecture-and-features" tabindex="-1">Architecture and Features <a class="header-anchor" href="#architecture-and-features" aria-label="Permalink to &quot;Architecture and Features&quot;">​</a></h2><p>The module combines four core subsystems:</p><ol><li><p><strong>Unified Order Inbox:</strong></p><ul><li>Centralized collection of orders from the website, Avito, messaging apps, and marketplaces.</li><li>Smart Clipboard Paste: automated extraction of customer name, phone number, delivery address, and order items from chat transcripts.</li><li>Canned Responses: pre-configured message templates (&quot;Order confirmed&quot;, &quot;Ready for dispatch&quot;, &quot;Payment details&quot;) with one-click direct dispatch to Telegram and WhatsApp.</li><li>1-Click Sale Processing: automated inventory deduction according to FIFO rules and sales log recording.</li></ul></li><li><p><strong>Showcase Product Catalog:</strong></p><ul><li>Single-switch product visibility control.</li><li>Visual badges (&quot;Hit&quot;, &quot;New&quot;, &quot;Custom Order&quot;, &quot;In Stock&quot;).</li><li>Independent showcase price (can differ from the baseline retail price).</li><li>Markdown descriptions and image galleries.</li></ul></li><li><p><strong>Store Profile &amp; Customization:</strong></p><ul><li>Craft workshop title, tagline, about story, and shipping conditions.</li><li>Direct contact links (Phone, Telegram, WhatsApp, Email).</li><li>Integration with Yandex Forms or Web3Forms for seamless checkout.</li></ul></li><li><p><strong>Universal Publishing Transport:</strong></p><ul><li><strong>Local Folder / ZIP Export:</strong> export the built site to local disk for manual hosting or handover.</li><li><strong>FTP / FTPS:</strong> direct upload to standard web hosting with incremental SHA-256 checks (avoids re-uploading unchanged assets).</li><li><strong>S3-Compatible Cloud Storage:</strong> Yandex Cloud, Selectel, VK Cloud, MinIO, AWS S3.</li><li><strong>GitHub Pages:</strong> automated direct deployment to the <code>gh-pages</code> branch using the official REST API.</li><li>Hardware-backed DPAPI credential encryption for hosting tokens and passwords.</li></ul></li></ol><hr><h2 id="step-by-step-guide" tabindex="-1">Step-by-Step Guide <a class="header-anchor" href="#step-by-step-guide" aria-label="Permalink to &quot;Step-by-Step Guide&quot;">​</a></h2><h3 id="step-1-prepare-products-for-the-showcase" tabindex="-1">Step 1. Prepare Products for the Showcase <a class="header-anchor" href="#step-1-prepare-products-for-the-showcase" aria-label="Permalink to &quot;Step 1. Prepare Products for the Showcase&quot;">​</a></h3><ol><li>Navigate to <strong>Web Store</strong> → subtab <strong>Showcase Catalog</strong> (or open the recipe card in <strong>Calculator</strong> on the Web Store tab).</li><li>Toggle the <strong>Publish</strong> switch for the desired products.</li><li>Click the configuration button (slider icon) to specify the URL slug, badge, and description.</li></ol><h3 id="step-2-configure-store-details" tabindex="-1">Step 2. Configure Store Details <a class="header-anchor" href="#step-2-configure-store-details" aria-label="Permalink to &quot;Step 2. Configure Store Details&quot;">​</a></h3><ol><li>Open the <strong>Profile &amp; Styling</strong> subtab.</li><li>Fill in your workshop name, tagline, and city.</li><li>Add messenger contact handles and shipping details.</li><li>Click <strong>Save Profile</strong>.</li></ol><h3 id="step-3-configure-transport-and-deploy" tabindex="-1">Step 3. Configure Transport and Deploy <a class="header-anchor" href="#step-3-configure-transport-and-deploy" aria-label="Permalink to &quot;Step 3. Configure Transport and Deploy&quot;">​</a></h3><ol><li>Open the <strong>Publishing Transport</strong> subtab.</li><li>Select the desired deployment method (<em>Local Folder</em>, <em>GitHub Pages</em>, or <em>FTP</em>).</li><li>Enter credentials and click <strong>Test Connection</strong>.</li><li>Once verified, click <strong>Save Transport</strong>.</li><li>In the top showcase bar, click <strong>Publish Website</strong>.</li></ol><p>The system compiles the static site, optimizes images, builds the order cart, and deploys the bundle to your chosen host.</p><hr><h2 id="order-inbox-workflow" tabindex="-1">Order Inbox Workflow <a class="header-anchor" href="#order-inbox-workflow" aria-label="Permalink to &quot;Order Inbox Workflow&quot;">​</a></h2><p>When a client places an order or messages you in chat:</p><ol><li>Open the <strong>Order Inbox</strong> tab.</li><li>If the customer texted in chat, copy the conversation and click <strong>Smart Paste</strong>. The system automatically extracts customer information and line items.</li><li>Click <strong>Reply</strong> to choose a quick response template and jump directly to Telegram or WhatsApp.</li><li>When the piece is completed and shipped, click <strong>Complete Sale</strong>: the system deducts stock via FIFO and records the revenue.</li></ol>',20)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
